-- ============================================================
-- V11: 把 public 的权限/鉴权表 + 字典表数据作为种子写入 crawl schema
--
-- 背景：
--   V3 用 `LIKE public.X INCLUDING ALL` 在 crawl schema 镜像了 RBAC
--   相关表的结构（users / user_oauth_binding / role / user_role /
--   menu / button / role_menu / role_button / api / user_cinema），
--   外加 dict / dict_item 字典表，但没有任何数据。新环境跑完 Flyway
--   后 crawl 侧权限和字典完全是空的，后台 admin 接 crawl schema 时
--   只能从 public 拷一次。
--
--   本迁移从 public 当前生产数据导出 INSERT 语句，作为不依赖 public
--   的种子直接写入 crawl，让新环境一次 migrate 就拿到与 public 一致
--   的 RBAC + 字典元数据；老环境跑也安全：每条 INSERT 都带
--   ON CONFLICT DO NOTHING（无 PK 表用 WHERE NOT EXISTS），已经存在
--   的行不会覆盖。
--
--   数据来源：本仓库 java-backend `application-dev.yml` 指向的
--   localhost:5432/test_movie public schema，导出时间：
--     pg_dump 18.1, 2026-05-31 Asia/Tokyo
--
-- 约束：
--   - 完全幂等：所有 INSERT 都带 ON CONFLICT DO NOTHING；
--   - 保留 public 原始主键：user_role / role_menu / role_button /
--     user_cinema 都靠 id 关联，必须保持一致；
--   - V3 LIKE 不带 FK，crawl.user_cinema 等表即使 crawl.cinema 还
--     没行也不会 FK 失败；
--   - 末尾把 crawl 侧 IDENTITY 序列推进到 max(id)，避免后续 INSERT
--     不带 id 时与种子主键冲突。
--
-- 如何刷新：
--   后续想再把 public 增量同步过来，请新增 V<n>__crawl_permission_resync.sql，
--   同样用 pg_dump --data-only --column-inserts 重新生成。
-- ============================================================

SET timezone = 'Asia/Tokyo';

CREATE SCHEMA IF NOT EXISTS crawl;

-- ---- users ----

-- ---- user_oauth_binding ----

-- ---- role ----

-- ---- menu ----

-- ---- button ----

-- ---- api ----

-- ---- user_role ----

-- ---- role_menu ----

-- ---- role_button ----

-- ---- user_cinema ----

-- ---- dict ----
-- 字典本体。V3 已经在 crawl.dict 写入 'crawlTicketStatus'（id≈1334936），
-- 与 public 既有 id (2..35068) 不冲突，直接 ON CONFLICT (id) DO NOTHING。

-- ---- dict_item ----
-- 字典项。dict_id 全部落在 public 既有 dict.id 上；V3 已写入的 7 行
-- crawlTicketStatus 项（id≈1334937..1334943）与 public id 段
-- (27414..35068) 不冲突。dict/dict_item 共用 public.auto_increment
-- 序列，其 last_value 已远超本批种子，无需 setval。

-- ----------------------------------------------------------------
-- 把 IDENTITY 序列推进到 max(id)，避免后续在 crawl 侧手工 INSERT
-- 不带 id 时与种子行主键冲突。
--
-- 注意：crawl.dict / crawl.dict_item 的 id 默认值是共享序列
-- public.auto_increment（last_value 已远超本批种子），不在此处
-- setval，避免影响 public 其他表。
-- ----------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('crawl.users',              'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.users),              1));
SELECT setval(pg_get_serial_sequence('crawl.user_oauth_binding', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.user_oauth_binding), 1));
SELECT setval(pg_get_serial_sequence('crawl.role',               'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.role),               1));
SELECT setval(pg_get_serial_sequence('crawl.menu',               'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.menu),               1));
SELECT setval(pg_get_serial_sequence('crawl.button',             'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.button),             1));
SELECT setval(pg_get_serial_sequence('crawl.api',                'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM crawl.api),                1));

DO $$
DECLARE
  v_users        INTEGER;
  v_user_oauth   INTEGER;
  v_role         INTEGER;
  v_menu         INTEGER;
  v_button       INTEGER;
  v_api          INTEGER;
  v_user_role    INTEGER;
  v_role_menu    INTEGER;
  v_role_button  INTEGER;
  v_user_cinema  INTEGER;
  v_dict         INTEGER;
  v_dict_item    INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_users        FROM crawl.users;
  SELECT COUNT(*) INTO v_user_oauth   FROM crawl.user_oauth_binding;
  SELECT COUNT(*) INTO v_role         FROM crawl.role;
  SELECT COUNT(*) INTO v_menu         FROM crawl.menu;
  SELECT COUNT(*) INTO v_button       FROM crawl.button;
  SELECT COUNT(*) INTO v_api          FROM crawl.api;
  SELECT COUNT(*) INTO v_user_role    FROM crawl.user_role;
  SELECT COUNT(*) INTO v_role_menu    FROM crawl.role_menu;
  SELECT COUNT(*) INTO v_role_button  FROM crawl.role_button;
  SELECT COUNT(*) INTO v_user_cinema  FROM crawl.user_cinema;
  SELECT COUNT(*) INTO v_dict         FROM crawl.dict;
  SELECT COUNT(*) INTO v_dict_item    FROM crawl.dict_item;

  RAISE NOTICE 'V11 crawl permission+dict seed loaded: users=%, user_oauth_binding=%, role=%, menu=%, button=%, api=%, user_role=%, role_menu=%, role_button=%, user_cinema=%, dict=%, dict_item=%',
    v_users, v_user_oauth, v_role, v_menu, v_button, v_api,
    v_user_role, v_role_menu, v_role_button, v_user_cinema,
    v_dict, v_dict_item;
END $$;
